sys_script_include.script:
var AooPemyUtilsAjax = Class.create();
AooPemyUtilsAjax.prototype = Object.extendsObject(global.AbstractAjaxProcessor, {

    getAvailableDates: function() {
        var trainingNameSysId = this.getParameter('sysparm_training_name');
        var dates = [];

        // Consulta a tabela de treinamentos para buscar as datas disponíveis
        var gr = new GlideRecord('x_1590789_aoopemy_training_schedules');
        gr.addQuery('training_name', trainingNameSysId);
        gr.addQuery('training_date', '>', gs.endOfToday()); // Filtra apenas datas futuras
        gr.query();

        while (gr.next()) {
            var date = gr.getValue('training_date'); // Pega a data do treinamento
            dates.push(date); // Adiciona a data ao array
        }

		gs.info("Date: "+ JSON.stringify(dates));
        return JSON.stringify(dates); // Retorna as datas como uma string JSON
    },

	getRegistrationCount: function() {
        var trainingNameSysId = this.getParameter('sysparm_training_name');

		gs.info(trainingNameSysId);
        var userId = this.getParameter('sysparm_user');
		gs.info(userId);

        // Consulta a tabela de matrículas para contar as inscrições do usuário no curso
        var gr = new GlideRecord('x_1590789_aoopemy_training_enrollments');
        gr.addQuery('training_schedules.training_name', trainingNameSysId);
        gr.addQuery('registered_user', userId);
        gr.query();

		gs.info(gr.getRowCount());

        return gr.getRowCount(); // Retorna o número de matrículas
    },


	isUserRegistered: function() {

		var trainingNameSysId = this.getParameter('sysparm_training_name');
        var trainingDate = this.getParameter('sysparm_training_date');
        var userId = this.getParameter('sysparm_user');


		gs.info("Valor da data: " + trainingDate);
        // Consulta a tabela de matrículas para verificar se o usuário já está matriculado
        var gr = new GlideRecord('x_1590789_aoopemy_training_enrollments');
        gr.addQuery('training_schedules.training_name', trainingNameSysId);
        gr.addQuery('training_schedules.training_date', trainingDate);
        gr.addQuery('registered_user', userId);
        gr.query();


		gs.info(gr.hasNext());
        return gr.hasNext() ? 'true' : 'false'; // Retorna 'true' se o usuário já estiver matriculado
    },

	getSchedulerSysId: function() {

		var trainingNameSysId = this.getParameter('sysparm_training_name');
        var trainingDate = this.getParameter('sysparm_training_date');

		var schedulerSysIdAndSeats = [];

		gs.info("Valor da data: " + trainingDate);
        // Consulta a tabela de matrículas para verificar se o usuário já está matriculado
        var gr = new GlideRecord('x_1590789_aoopemy_training_schedules');
        gr.addQuery('training_name', trainingNameSysId);
        gr.addQuery('training_date', trainingDate);
        gr.query();

		if (gr.next()) {
            var schedulerSysIdSeat = gr.getValue('sys_id'); // Pega o SysId
            schedulerSysIdAndSeats.push(schedulerSysIdSeat); // Adiciona a data ao array
			schedulerSysIdSeat = gr.getValue('available_slots'); // Pega a data do treinamento
            schedulerSysIdAndSeats.push(schedulerSysIdSeat); // Adiciona a data ao array
        }

		gs.info("SchedulerSysIdAndSeats "+ JSON.stringify(schedulerSysIdAndSeats));
        return JSON.stringify(schedulerSysIdAndSeats); // Retorna as datas como uma string JSON
    },

    type: 'AooPemyUtilsAjax'
});
